// SkillDesk Academy curriculum: readable, editable course data. All material works offline.
const B=(title,text,bullets=[],code='',tip='')=>({title,text,bullets,code,tip});
const Q=(question,options,correct,explanation)=>({question,options,correct,explanation});
const L=(id,title,minutes,lead,blocks,lab,quiz)=>({id,title,minutes,lead,blocks,lab,quiz});
const COURSES=[
{
 id:'foundations', title:'IT Support Foundations', subtitle:'Start here: computers, terminology, and what an IT technician actually does.', icon:'monitor',level:'Beginner',accent:'#6d7eff',category:'Core skills', outcomes:['Understand the parts of an IT environment','Explain common IT support terminology','Follow a basic troubleshooting process'],
 lessons:[
 L('what-is-it','What does IT support do?',12,'IT support helps people use technology reliably, securely, and confidently.',[
 B('The job in plain English','A support technician fixes or prevents problems involving laptops, desktops, accounts, printers, networks, software, and access. The goal is not to memorize every answer. It is to ask the right questions, narrow the cause, and communicate a useful fix.',['Help desk: first contact for incidents and requests.','Desktop support: hands-on device setup and repair.','Systems/network teams: maintain shared infrastructure.']),
 B('Learn the workflow','An incident means something stopped working. A service request asks for a normal change, such as installing an approved app. Both often enter a ticketing system so someone owns them and users receive updates.',['Listen → clarify → check scope → test → fix or escalate → document.','Treat users respectfully, even when the issue is simple.','Never request a person’s password.'],'','Support is as much communication as it is technical work.')
 ],['Describe the difference between an incident and a request.','Write down three questions you would ask when someone says “my computer is broken.”'],[
 Q('A user asks for an approved mouse to be ordered. This is usually a…',['Security incident','Service request','Network outage'],1,'A normal equipment request is a service request.'),
 Q('What should you do first when a user says “the internet is broken”?',['Replace the router','Clarify what fails and who is affected','Reinstall Windows'],1,'Scoping the issue before changing anything saves time.')]),
 L('computer-basics','Hardware vs. software',14,'Every computer combines physical parts, instructions, and data.',[
 B('Three layers','Hardware is what you can touch. Software is the instructions that run. Data is what software works with. The operating system coordinates hardware, applications, user accounts, and files.',['Hardware: CPU, RAM, storage, keyboard, monitor, network adapter.','System software: Windows, macOS, Linux, device drivers.','Applications: browser, word processor, video meeting app.']),
 B('How to isolate a problem','One app crashing suggests an app issue; every app crashing suggests a wider OS, memory, storage, or hardware problem. A blank monitor might be display power, a cable, the laptop output, or a failure to boot. Do not assume the visible symptom proves the cause.',['Ask what changed before the issue appeared.','Check the simplest reversible causes first.','Change one variable at a time.'])
 ],['List five pieces of hardware on a device near you.','Name its operating system and two applications.'],[
 Q('Which is software?',['A graphics card','A keyboard','A web browser'],2,'A browser is an application.'),
 Q('A printer stops working only in one app. What is a reasonable first suspicion?',['Application settings','Building power failure','Dead motherboard'],0,'A problem isolated to one program may be its configuration.')]),
 L('inside-computer','How a computer works',16,'Follow what happens between pressing a key and seeing a result.',[
 B('The main players','The CPU executes instructions. RAM temporarily holds working information. Storage preserves files and installed apps across restarts. The motherboard connects components, and the power supply provides electrical power.',['CPU = processor; typically more cores help concurrent work.','RAM = short-term workspace; insufficient RAM may cause slowdowns.','SSD/HDD = long-term storage; an SSD is typically faster.']),
 B('Start-up, simplified','When powered on, firmware (UEFI/BIOS) initializes hardware and starts a bootloader, which launches the operating system. A failure before the logo appears is different from an OS that freezes after sign-in.',['Firmware/POST problems often appear before Windows loads.','A login or desktop problem usually happens later in boot.','Back up important files before risky repair work.'])
 ],['Draw a simple CPU → RAM → storage relationship.','Think of one symptom that could signal low RAM rather than full storage.'],[
 Q('Which component normally keeps files when power is off?',['RAM','SSD','CPU'],1,'Persistent storage such as an SSD retains data.'),
 Q('UEFI firmware generally runs…',['Before the operating system','Only inside Chrome','After logging into Windows'],0,'Firmware initializes hardware prior to OS startup.')]),
 L('safe-support','Safety, privacy, and permissions',13,'Good technicians protect people and data before touching settings.',[
 B('Physical and data safety','Power down and unplug equipment before opening it, follow approved electrostatic-discharge procedures, and never open a power supply. Backups and authorization matter: a successful repair that destroys documents is still a failure.',['Confirm you are permitted to make the change.','Do not open personal files without a documented need.','Be cautious around swollen batteries, liquid damage, and exposed electricity.']),
 B('Least privilege','Use the lowest access needed for the job. Separate admin accounts from everyday activity when organizational policy requires it. Share sensitive information only through approved channels.',['Verify a caller before resetting account access.','Lock the screen when stepping away.','Stop and escalate signs of a security breach.'],'','Never ask someone to read out a password or multifactor authentication code.')
 ],['Write two things you would confirm before wiping a computer.','Explain why a technician should not disable antivirus just to get an app running.'],[
 Q('A caller asks you to tell them another employee’s password. You should…',['Share it if they sound urgent','Refuse and follow identity/access policy','Guess the password'],1,'Passwords should never be disclosed.'),
 Q('Before a destructive OS reinstall, first confirm…',['Favorite wallpaper','Authorization and a verified backup','Monitor brightness'],1,'Protect data and obtain approval first.')]),
 L('support-language','IT vocabulary and first ticket',16,'Learn the words you will hear all day and use them to create a useful ticket.',[
 B('Words that matter','An endpoint is a device used by an employee. A server provides shared services. A client requests services. An account controls identity and permissions. A patch changes software, often to fix bugs or security risks.',['Downtime: time a service is unavailable.','Scope: which devices, users, or sites are affected.','Workaround: temporary way to keep work moving.','Escalation: handoff when risk, access, or expertise requires it.']),
 B('Write a clear ticket','Capture who is affected, what fails, when it began, the exact error, the business impact, tests performed, the outcome, and the next owner. “Internet broken” is not useful. “Only workstation 12 cannot browse; Wi-Fi connected, gateway reachable, DNS lookup fails” is actionable.',['Use facts and timestamps, not guesses.','Document changes before and after.','Tell the user what happens next.'])
 ],['Draft a ticket for a mouse that stops moving after a Windows update.','Add a concise summary, impact, steps tried, and next step.'],[
 Q('What belongs in a support ticket?',['Exact symptoms and steps tried','A copy of the user’s password','Unverified blame'],0,'Specific evidence makes tickets useful.'),
 Q('A temporary fix that lets the user work is a…',['Workaround','Patch panel','Bootloader'],0,'A workaround restores function until the root fix is ready.')])
 ]},
{
 id:'hardware', title:'Hardware & Device Repair', subtitle:'PC components, boot issues, storage, monitors, and printers.',icon:'cpu',level:'Beginner',accent:'#f49a57',category:'Devices',outcomes:['Identify the most important PC components','Diagnose basic boot and peripheral faults','Know when hardware repair needs escalation'],
 lessons:[
 L('pc-components','Recognize PC components',16,'You do not need to build a PC to understand its major parts.',[
 B('What parts do','CPU processes instructions; a cooler removes heat; RAM stores active working data; storage holds Windows and documents; motherboard connects everything; GPU handles graphics; PSU powers desktop components.',['Laptop components may be soldered and not user-replaceable.','Fans and vents matter because heat can cause throttling or shutdowns.','A GPU is not necessary for every office PC.']),
 B('Compatibility basics','Replacement RAM must match the supported generation and form factor. Storage may use SATA or NVMe interfaces. Check the exact device model and service manual before purchasing or disassembling parts.',['Record device serial/model in the ticket, not publicly.','Check warranty and repair authorization.','Power down and follow ESD procedures first.'])
 ],['Find a computer model and look up its RAM and storage specifications in its manual.','Explain what CPU, RAM, and storage each do in one sentence.'],[
 Q('What primarily handles temporary working data?',['RAM','SSD','Power supply'],0,'RAM is temporary, fast working memory.'),
 Q('Before choosing a replacement part, first check…',['Case color','Model and compatibility','The user’s browser history'],1,'Correct interfaces and supported specifications matter.')]),
 L('boot-issues','Boot problems and POST',17,'A computer that never turns on is not the same as one that cannot launch Windows.',[
 B('Separate the symptoms','No power means no lights or fans; power with no display could be monitor, cable, graphics, or POST; an OS recovery screen means the system got further in the boot sequence. Note LED and beep diagnostics from the vendor.',['Check outlet, charger, battery, display power, and cables.','Disconnect nonessential peripherals if approved.','Use vendor diagnostic codes and service instructions.']),
 B('Why simple checks win','A black screen might be brightness or an input-source issue. Do reversible checks before firmware changes, component replacement, or reinstalling an OS. If you suspect an unsafe electrical fault or damaged battery, stop.',['Confirm if a dock or external display is involved.','Record exactly what appears on-screen.','Escalate if it is under warranty or beyond permissions.'])
 ],['Write a three-branch decision tree: no power, power/no display, and Windows will not load.','List the first two safe checks for each branch.'],[
 Q('A PC shows a Windows recovery screen. Which stage was reached?',['Some OS boot activity','Only the wall outlet','Nothing after power'],0,'Windows recovery means firmware and boot proceeded at least partway.'),
 Q('Best early check for a black external monitor?',['Replace motherboard','Confirm display input and cable','Format hard drive'],1,'Check the simple signal path first.')]),
 L('storage-memory','RAM, storage, and performance',17,'Find the difference between a slow machine and a full machine.',[
 B('Two common bottlenecks','Low available RAM can cause paging: the OS moves working data to slower storage. Low disk space can block updates and downloads. A failing drive can cause errors and long pauses; treat signs of drive failure as a data-protection priority.',['Task Manager shows memory, disk, and CPU activity.','Avoid deleting unknown system files to free space.','A drive health warning should trigger backup/escalation.']),
 B('Measure first','Ask when slowness happens and compare idle vs. workload resource usage. Startup apps, background updates, malware, thermals, RAM pressure, and storage faults can all look like “a slow laptop.”',['Check free space and overall resource utilization.','Restart approved apps and investigate recent changes.','Document what improved or did not.'])
 ],['Open Task Manager and identify CPU, memory, and disk percentages.','Find available storage space in your OS settings; do not delete files for this exercise.'],[
 Q('A laptop has nearly no free SSD space. A likely consequence is…',['Updates may fail','Wi-Fi signal increases','Battery capacity doubles'],0,'The OS and apps often require free space.'),
 Q('When an SSD reports health failures, prioritize…',['Data backup and escalation','Deleting all files','Increasing screen resolution'],0,'Protect data before experimenting with a potentially failing drive.')]),
 L('peripherals','Printers, monitors, and USB',16,'Peripheral problems are often caused by connection, selection, or driver settings.',[
 B('Follow the connection','For a monitor: power → selected input → physical cable/dock → OS display configuration. For a printer: power → connection → correct printer selection → queue → driver → service or hardware.',['USB-C connectors do not always support identical display/data features.','A stalled printer queue can stop new jobs.','Test with a known-good cable or port when approved.']),
 B('Check scope before replacing','Does the printer fail for one user or everyone? Can other apps print? Is the printer online? Does it have paper or error lights? Separating device-wide and user-only symptoms helps isolate cause.',['Use approved driver sources.','Avoid printing sensitive test documents.','Clear a print queue only after considering pending user jobs.'])
 ],['Sketch a 5-step checklist for a printer that shows “offline.”','Explain why the correct monitor input matters.'],[
 Q('Only one person cannot print to a shared printer. Your first focus is…',['That user’s settings/connection','Replace building-wide router','Replace all printers'],0,'A one-user failure points to a local configuration issue.'),
 Q('When using a USB-C dock with no monitor output, check…',['Display support, dock, and cable','Keyboard language only','Antivirus quarantine first'],0,'USB-C capabilities and docks vary.')])
 ]},
{
 id:'operating-systems',title:'Windows & Operating Systems',subtitle:'Become comfortable with Windows tools, files, accounts, drivers, and Linux basics.',icon:'layout',level:'Beginner',accent:'#36b8af',category:'Systems',outcomes:['Navigate Windows administration basics','Recognize account and permissions issues','Use everyday OS troubleshooting tools'],
 lessons:[
 L('os-role','What the operating system controls',15,'The OS is the manager between applications, people, files, and hardware.',[
 B('OS responsibilities','Windows, macOS, and Linux schedule programs, manage memory, enforce access, handle files and disks, and talk to devices through drivers. Applications generally depend on the OS to use hardware safely.',['Kernel: the core of the operating system.','Process: a running program instance.','Service: background component that does work without a visible window.']),
 B('Know your environment','Support teams should capture OS version, hardware model, and relevant app versions before applying a fix. A procedure for one version may not apply to another.',['Check Windows: Settings → System → About.','Use built-in Settings and Task Manager before third-party “optimizers.”','Updates can improve security but sometimes require restarts.'])
 ],['Identify your OS and version.','Write one example each of a process, a service, and a device driver.'],[
 Q('A device driver is primarily used to…',['Communicate with hardware','Store passwords in plain text','Replace RAM'],0,'Drivers allow the OS to work with specific devices.'),
 Q('The kernel is…',['The OS core','A USB cable','A text editor'],0,'The kernel handles fundamental system operations.')]),
 L('windows-tools','Windows tools you will use',19,'Learn where to find trustworthy troubleshooting signals.',[
 B('Four key tools','Task Manager shows running apps and performance; Device Manager shows connected hardware and driver errors; Event Viewer holds system and application logs; Settings offers network, storage, app, and update configuration.',['Task Manager: Ctrl + Shift + Esc.','Device Manager: inspect warnings and hardware properties.','Event Viewer: correlate errors with when symptoms started.']),
 B('Use logs carefully','An event warning does not automatically explain the problem. Match timestamps and symptoms; search approved documentation for unfamiliar event identifiers. A high CPU percentage during a demanding task is not necessarily a fault.',['Measure first and compare known-good behavior.','Do not disable services randomly.','Document findings and restore changes if they do not help.'],'taskmgr\nmsinfo32\ndevmgmt.msc','These are examples of Windows Run commands, not commands executed here.')
 ],['Open Task Manager and find the memory utilization view.','Find Device Manager without changing any settings.'],[
 Q('Which Windows tool displays live CPU and memory use?',['Task Manager','Notepad','Paint'],0,'Task Manager includes the Performance tab.'),
 Q('An Event Viewer error is…',['A clue to correlate with symptoms','Proof the hard drive is broken','Always malware'],0,'Logs require context.')]),
 L('files-permissions','Files, users, and permissions',17,'Many “the file is gone” issues are path, sync, or permissions issues.',[
 B('Paths and file types','Files live at paths such as C:\\Users\\Sam\\Documents\\report.docx. Extensions often indicate format but do not guarantee a file is safe. The Recycle Bin, searches, cloud sync status, and the actual save location are useful clues.',['Absolute path: full location from drive or root.','Extension: suffix such as .pdf or .xlsx.','Hidden items: do not expose or delete system content casually.']),
 B('Identity and access','Accounts identify users; groups simplify permissions; administrative rights authorize system-wide changes. “Access denied” does not mean a technician should automatically grant everyone access.',['Verify the user should have access.','Prefer adding the right group instead of broad permissions.','Follow approval procedures for permission changes.'])
 ],['Find a document and identify its full path and extension.','Describe what you would check before giving access to a shared folder.'],[
 Q('A user cannot open a restricted shared folder. Best first step?',['Verify identity and intended access','Make the folder public','Disable all permissions'],0,'Authorization comes before access changes.'),
 Q('A file extension usually suggests…',['File format','CPU speed','Wi-Fi password'],0,'Extensions like .pdf or .txt indicate likely file types.')]),
 L('apps-updates','Apps, drivers, and updates',17,'Software fixes are safer when you follow vendor and organization procedures.',[
 B('Order of operations','Confirm the error, scope, version, and recent changes. Try an approved app restart, sign-in check, disk space check, or repair option before reinstalling. Install drivers and updates from trusted vendor or managed channels.',['Save user work before rebooting.','Check whether a maintenance window is required.','Use rollback only when justified and approved.']),
 B('Avoid the “magic fix” trap','Running random cleanup scripts and downloading “driver updater” tools can create larger security and reliability issues. A fix must address the symptom and be documented so another technician can reproduce the reasoning.',['Track version before and after.','Reboot when required and verify the original issue.','Escalate if the update is managed by IT policy.'])
 ],['Draft a safe 5-step response when one approved application crashes.','Identify one source you would trust for a device driver.'],[
 Q('Best source for a corporate laptop driver?',['Approved OEM/IT channel','Random pop-up website','Unknown “one-click fixer”'],0,'Vendor and managed sources are safer.'),
 Q('After an update, the next step is to…',['Verify the original problem','Delete the ticket immediately','Disable future updates'],0,'Always verify the actual outcome.')]),
 L('linux-macos','macOS and Linux essentials',17,'Support skills transfer across operating systems when you understand concepts.',[
 B('Shared concepts','macOS and Linux use similar concepts: files, accounts, processes, network settings, and permissions. Their interfaces differ. Linux paths begin at /, while macOS uses Unix-style paths and Finder for graphical navigation.',['Terminal: text-based command interface.','sudo: request elevated permissions under policy.','Package manager: installs software from configured sources.']),
 B('Low-risk read-only commands','On many Unix-like systems, pwd shows the current directory, ls lists entries, whoami shows the current account, and uname -a prints system information. Commands and options can differ by platform.',['Read the help/manual before running unfamiliar commands.','Never paste an unexplained internet script into a privileged shell.','Ask for approval before making managed-device changes.'],'pwd\nls\nwhoami\nuname -a')
 ],['Explain the difference between a path like C:\\Users and /home/user.','Write what pwd and ls reveal, without running risky commands.'],[
 Q('What does pwd typically show?',['Current working directory','Public Wi-Fi password','Printer driver'],0,'pwd prints the current working directory.'),
 Q('Why be careful with sudo?',['It can execute actions with elevated permissions','It disables all networking forever','It is a file format'],0,'Elevated access increases potential impact.')])
 ]},
{
 id:'networking',title:'Networking from Zero',subtitle:'Understand Wi-Fi, IP addresses, DNS, DHCP, routers, and basic network commands.',icon:'network',level:'Beginner → Intermediate',accent:'#46b2f0',category:'Networking',outcomes:['Understand how devices reach websites','Differentiate DNS, DHCP, routers, and switches','Diagnose common connection failures'],
 lessons:[
 L('network-path','How the internet works',18,'Think of networking as devices sending labeled packets along routes.',[
 B('The journey','A device sends data through a wired or wireless connection to its local network. The router connects networks and sends traffic toward destinations. Internet services respond and packets return. Applications depend on multiple layers all functioning.',['LAN: local network, such as an office.','WAN: larger network connecting locations.','Router: forwards between networks.','Switch: connects devices within a local network.']),
 B('Map the failure','If a laptop cannot reach any site but others can, suspect the device or local connection. If every device is offline, investigate the shared network or upstream service. Confirm the scope before rebooting shared equipment.',['Try a known-good second website.','Check Wi-Fi connected status vs. real connectivity.','Never disrupt shared networking without authorization.'])
 ],['Draw device → Wi-Fi access point → router → internet → website.','Explain why a router and a switch do different jobs.'],[
 Q('What normally forwards data between different IP networks?',['Router','Keyboard','SSD'],0,'Routers connect and route between networks.'),
 Q('If only one laptop is offline, first investigate…',['That laptop and its link','The entire internet globally','All switches in the building'],0,'Scope narrows the likely cause.')]),
 L('ip-addressing','IP addresses, gateways, and masks',20,'IP settings tell computers who they are and where to send traffic.',[
 B('Address essentials','IPv4 addresses look like 192.168.1.25. A subnet mask/prefix indicates which addresses are local. A default gateway is the router a device uses for off-network traffic. Private IPv4 ranges are commonly used inside organizations.',['IP address: identifies an interface on the network.','Subnet: set of addresses treated as local.','Default gateway: path to other networks.']),
 B('What common symptoms mean','An address beginning 169.254 on many devices can mean automatic self-assignment when DHCP fails. Duplicate addressing can break communications. A wrong gateway can allow local access while blocking the internet.',['Write down current settings before changing them.','Most managed endpoints use DHCP rather than a manually typed IP.','Do not assign static addresses without a plan.'],'ipconfig /all','Windows example. Read output; do not change IP settings during this exercise.')
 ],['Find IP address and default gateway in your network settings.','Describe why the default gateway matters.'],[
 Q('What is the typical purpose of the default gateway?',['Route traffic beyond the local subnet','Store documents','Set monitor brightness'],0,'The gateway carries off-subnet traffic.'),
 Q('An IPv4 address starting with 169.254 often hints at…',['Failure to obtain a DHCP lease','A fast VPN','A new monitor'],0,'Link-local addressing commonly appears when DHCP is unavailable.')]),
 L('dns-dhcp','DNS and DHCP explained',19,'Two background services make everyday networking easier.',[
 B('Names vs. numbers','DNS translates domain names such as example.com to IP addresses. DHCP usually provides an IP, network prefix/mask, gateway, and DNS server automatically. They solve different problems.',['DNS: “Where is this named service?”','DHCP: “What network settings should I use?”','A working Wi-Fi signal does not guarantee either service works.']),
 B('Diagnose the layers','If you can reach a known IP but not a named site, DNS becomes a suspect. If a device has no usable address, DHCP or local connectivity may be the issue. These are clues rather than absolute proof.',['Check if the issue affects one user or everyone.','Compare a known-good device on the same network.','Avoid changing enterprise DNS configurations without permission.'],'nslookup example.com\nipconfig /all')
 ],['Explain DNS using a phone contact analogy.','Write down what DHCP supplies to a laptop.'],[
 Q('Which service maps a website name to an IP address?',['DNS','DHCP','Bluetooth'],0,'DNS is the name-resolution system.'),
 Q('Which service commonly assigns clients their IP settings?',['DHCP','HDMI','BIOS'],0,'DHCP provides network configuration leases.')]),
 L('wifi-troubleshooting','Troubleshooting Wi-Fi',19,'Wi-Fi “connected” and internet “working” are not the same thing.',[
 B('Wireless basics','An access point provides Wi-Fi. Signal, interference, distance, authentication, and device settings affect connection quality. 2.4 GHz often travels farther but faces more interference; 5 GHz typically supports higher throughput with shorter practical range.',['SSID: Wi-Fi network name.','Authentication: permission to join network.','Captive portal: web sign-in common on guest networks.']),
 B('Useful isolation checks','Verify the right network, airplane mode, signal, and whether other clients are affected. Forget/rejoin only with permission and necessary credentials. Compare wired connectivity if available. Escalate broad outages.',['Do not ask a user to share a Wi-Fi password in public chat.','Avoid factory-resetting workplace access points.','Be alert to lookalike or rogue hotspots.'])
 ],['Write a safe checklist for “connected, no internet.”','Explain one reason Wi-Fi can work poorly despite full signal bars.'],[
 Q('What is an SSID?',['Network name','Device serial number','A disk format'],0,'SSID identifies a wireless network.'),
 Q('All office Wi-Fi clients lost access. Best approach?',['Investigate shared infrastructure and escalate','Reinstall every laptop','Change each user’s wallpaper'],0,'The shared scope points to network-level components.')]),
 L('network-commands','Network commands you can trust',22,'Simple read-only tests give much better clues than guessing.',[
 B('Three diagnostic commands','ipconfig /all displays Windows interface settings. ping tests whether packets receive replies (although firewalls can block responses). nslookup queries DNS. tracert reveals some hops a packet traverses, though filters may obscure hops.',['First: check local IP and gateway.','Second: test local and external connectivity as permitted.','Third: compare DNS behavior if names fail.']),
 B('Interpret cautiously','A failed ping does not prove a service is down: ICMP can be blocked. DNS results can vary. Collect observations and timestamps rather than declaring an outage from one command.',['On macOS/Linux, commands and flags differ.','Avoid scanning networks without explicit authorization.','Use the practice terminal in this website to rehearse safely.'],'ipconfig /all\nping 8.8.8.8\nnslookup example.com\ntracert example.com')
 ],['Open the website’s Terminal Lab and type help.','Try ipconfig, ping, and nslookup; explain what each simulated output indicates.'],[
 Q('A successful nslookup tells you primarily about…',['DNS name resolution','Laptop battery health','Printer toner'],0,'nslookup asks a DNS server about a name.'),
 Q('A failed ping always proves the destination is down.',['True','False'],1,'ICMP might be filtered even when a service works.')])
 ]},
{
 id:'security',title:'Cybersecurity for IT Support',subtitle:'Keep users safe with smart identity, phishing, backups, and endpoint hygiene.',icon:'shield',level:'Beginner',accent:'#a88cf1',category:'Security',outcomes:['Recognize suspicious support requests','Explain MFA and least privilege','Respond safely to common security concerns'],
 lessons:[
 L('phishing','Phishing and social engineering',18,'Attackers often target people rather than exploiting complicated technology.',[
 B('Spot manipulation','Phishing emails and messages may imitate trusted brands and use urgency, unusual links, attachments, or payment demands. The sender display name alone is not proof of identity; attackers can impersonate colleagues by voice or chat.',['Pause when messages demand urgent secrecy.','Check links and domains through approved methods.','Report suspicious messages using organization tools.']),
 B('Safer support response','Never ask the user to run an unverified command from an email. If someone clicked a suspicious link or entered credentials, follow the organization’s incident response process promptly. Avoid promising that no damage occurred.',['Collect facts without forwarding malicious attachments.','Escalate suspected credential theft quickly.','Do not shame a user who reports a mistake.'])
 ],['Write three red flags for a fake password-reset email.','Explain what you would do if someone reported entering credentials into a fake page.'],[
 Q('An email demands you enter an MFA code on a new website urgently. You should…',['Verify using an independent trusted channel','Enter it to be safe','Forward the code to the sender'],0,'A separate trusted channel is safer.'),
 Q('If a user reports phishing, the best response is…',['Prompt, calm reporting and escalation','Blame the user','Ignore it if no popup appeared'],0,'Fast nonjudgmental reporting reduces harm.')]),
 L('accounts-mfa','Passwords, MFA, and least privilege',17,'Identity protection sits at the center of modern support work.',[
 B('Authentication vs. authorization','Authentication proves who you are. Authorization decides what you may access. Multifactor authentication adds an independent factor, such as a passkey/security key or authenticator, beyond a password.',['Use approved password managers.','Do not share passwords or one-time codes.','Repeated unexpected MFA requests can signal an attack.']),
 B('Secure account support','Help desk account resets are sensitive. Verify identity with approved procedures, enforce least-privilege access, and record changes in tickets. Never bypass a policy for a convincing caller.',['Use approved reset and recovery workflows.','Restrict admin privileges to necessary work.','Escalate unusual requests for privileged access.'])
 ],['Explain authentication vs. authorization with a building-access analogy.','List two factors that differ from a memorized password.'],[
 Q('A user has signed in but lacks access to a file. The issue may involve…',['Authorization','Monitor brightness','Fan speed'],0,'Authorization governs permissions after identity is established.'),
 Q('An unexpected MFA approval prompt should generally be…',['Denied and reported','Approved quickly','Shared with a coworker'],0,'Unsolicited prompts may indicate attempted account access.')]),
 L('patching-backups','Updates, backups, and recovery',18,'Reliable recovery protects data as well as devices.',[
 B('Defense in layers','Updates fix known bugs and vulnerabilities. Endpoint protection, device encryption, secure configuration, backups, and user education reduce risk together. No single product makes a system invulnerable.',['Apply updates through managed channels.','Do not disable security controls without approval.','Encryption protects data on lost devices when implemented correctly.']),
 B('Backups are only useful if restore works','A useful backup plan considers what data is covered, how often it is copied, who can restore it, and whether restores have been tested. Sync is not always a backup: accidental deletion may propagate.',['Follow retention and privacy rules.','Protect backup access from compromise.','Test restoration procedures in approved settings.'])
 ],['List the data you would want protected before replacing an employee laptop.','Explain the difference between syncing a folder and retaining recoverable versions.'],[
 Q('Why test backups?',['To confirm restoration actually works','To increase screen brightness','To remove the OS'],0,'Unverified backups can fail during a real incident.'),
 Q('Which is true of security patches?',['They often close known vulnerabilities','They guarantee zero risk','They replace user training'],0,'Patching reduces exposure but does not remove all risk.')]),
 L('security-incidents','Responding to a suspected security incident',18,'Know your role and avoid destroying evidence.',[
 B('When to escalate','Unexpected ransomware notes, missing data, credential compromise, or unusual account activity deserve prompt incident escalation. Follow the employer’s runbook; unauthorized cleanup can overwrite evidence or worsen damage.',['Record time, symptoms, and affected devices.','Follow containment instructions from security staff.','Use an approved communication channel.']),
 B('Communication matters','Give users simple next steps and avoid speculating about causes or promising an outcome. Do not publicize sensitive ticket details. Security teams may direct a device to remain untouched pending investigation.',['Never investigate a colleague’s private data out of curiosity.','Do not connect suspicious USB drives.','If in doubt, pause and escalate.'])
 ],['Create a short incident ticket for a suspected account takeover.','Name two actions to avoid without the response team’s authorization.'],[
 Q('A computer shows a ransomware demand. First priority?',['Follow incident response procedures and escalate','Pay immediately from personal funds','Delete logs'],0,'Incidents require controlled response.'),
 Q('Why preserve logs in a suspected compromise?',['They may contain investigative evidence','They speed up the monitor','They can replace backups'],0,'Evidence can help determine what occurred.')])
 ]},
{
 id:'helpdesk',title:'Help Desk & Real Troubleshooting',subtitle:'Practice the process professional technicians use on real tickets.',icon:'headset',level:'Beginner → Intermediate',accent:'#ef78a8',category:'Support workflow',outcomes:['Use structured troubleshooting rather than guessing','Document and prioritize support tickets','Communicate fixes and escalations clearly'],
 lessons:[
 L('seven-steps','A repeatable troubleshooting method',20,'Method beats random fixes.',[
 B('A practical sequence','1. Identify symptoms and scope. 2. Establish likely causes. 3. Test the safest hypothesis. 4. Plan the next action and assess risk. 5. Apply an authorized fix. 6. Verify functionality and prevention. 7. Document findings and follow up.',['Ask what changed, when it began, and who is affected.','Use one test at a time when possible.','Escalate when risk or access exceeds your role.']),
 B('Know what not to do','Do not wipe a machine or reset shared infrastructure as a first attempt. Observe before acting. A temporary workaround can help productivity, but still document the underlying issue if unresolved.',['Prefer reversible checks.','Save open user work before restart.','Confirm with the user that the original task works.'])
 ],['Apply the seven steps to a laptop that cannot connect to a video call.','Identify two safe tests before reinstalling anything.'],[
 Q('Which comes before changing network settings?',['Gather symptoms and scope','Buy a new router','Close the ticket'],0,'Diagnosis precedes changes.'),
 Q('After applying a fix, always…',['Verify the original problem is resolved','Assume success silently','Erase the evidence'],0,'Verification confirms success.')]),
 L('ticket-quality','Tickets, priority, and SLAs',17,'A good ticket can save the next technician hours.',[
 B('Make the ticket actionable','A strong ticket has user/contact, asset, impact, urgency, symptoms, timestamps, error messages, steps tried, results, and owner. Priority usually combines impact and urgency under an organization’s policy.',['One user’s inconvenience and a whole-site outage differ in impact.','A deadline can affect urgency.','Do not invent an SLA or promise a resolution time.']),
 B('Use a helpful update','“I confirmed the account works on another device. I’m checking this laptop’s saved credentials next. I’ll update you after that test.” This is more reassuring than “working on it.”',['Summarize confirmed facts.','State a next step and owner.','Avoid blaming other teams or the user.'])
 ],['Draft a high-priority ticket for a whole-office outage.','Rewrite “computer no work” as a helpful issue summary.'],[
 Q('Priority is commonly based on…',['Impact and urgency','User’s favorite color','Age of the laptop alone'],0,'Business impact and urgency guide priority.'),
 Q('A strong ticket update includes…',['What is known and the next step','A guessed root cause stated as fact','The user’s password'],0,'Clear, factual updates build trust.')]),
 L('remote-support','Remote support and customer communication',18,'Remote work still requires consent and a clear process.',[
 B('Set expectations','Introduce yourself, verify identity through policy, explain what you will do, and request permission before remote viewing or controlling a user’s screen. Ask users to close unrelated sensitive content.',['Use approved remote support tools only.','Narrate changes in plain language.','Avoid unnecessary access to private content.']),
 B('Teach without overwhelming','Instead of “your DNS resolver is misconfigured,” say “your computer can connect, but it’s having trouble finding websites by name. I’m checking the name lookup settings.” Confirm comprehension and invite the user to try the final step themselves.',['Avoid acronyms unless explained.','Provide short reproducible steps.','Close with prevention tips if relevant.'])
 ],['Write a 30-second opening script for an approved remote support session.','Translate “DHCP lease failure” into simple language.'],[
 Q('Before controlling a user’s screen you need…',['Consent and approved access','Only their keyboard model','Their personal email password'],0,'Access must be authorized and transparent.'),
 Q('Best support communication uses…',['Clear language and frequent factual updates','Unexplained acronyms','Blame'],0,'Users need clear explanations.')]),
 L('escalation','When and how to escalate',16,'Escalation is responsible teamwork, not failure.',[
 B('Escalation triggers','Escalate if you lack permission, a security incident is suspected, shared infrastructure is involved, important data is at risk, or troubleshooting has exhausted safe tests. Check the runbook for the correct team.',['Functional escalation: route to specialized team.','Hierarchical escalation: involve management when policy or impact requires it.','Urgent incidents may need immediate response channels.']),
 B('A great handoff','Include a concise issue, exact impact, environment, reproduction steps, results, recent changes, and any temporary workaround. Avoid saying only “not working, please fix.”',['State what has been ruled out.','Identify any planned or unsafe steps not taken.','Keep ticket ownership and user communications clear.'])
 ],['Write an escalation note for suspected shared DNS failure.','Name one situation where continuing to experiment would create risk.'],[
 Q('A ticket needs admin rights that you do not have. Do you…',['Escalate through policy','Borrow someone’s credentials','Disable permission checks'],0,'Do not bypass access controls.'),
 Q('An escalation should include…',['Evidence and tests already performed','Only “broken”','Unverified assumptions'],0,'The next team needs context.')]),
 L('closing-the-loop','Verify, document, and prevent repeat issues',17,'Fixing the symptom is not the same as closing the loop.',[
 B('Check the user’s real task','If you repaired Outlook, ask the user to send and receive a message. If you fixed printing, confirm a permitted test job prints. Reproduce the original behavior to ensure success.',['Note the cause if confirmed, otherwise label it suspected.','Record the change and follow-up.','Respect privacy while testing.']),
 B('Build a knowledge base','If a known issue repeats, an internal knowledge article can capture symptoms, prerequisites, safe solution, validation, rollback, and escalation criteria. This makes future cases faster and more consistent.',['Use concise, numbered steps.','Version instructions for specific environments.','Review articles when systems change.'])
 ],['Write a six-line knowledge article for a frozen app.','Define the verification step and when to escalate.'],[
 Q('A fix is verified when…',['The original user task works again','An unrelated website loads','The technician thinks it probably worked'],0,'Test the actual reported issue.'),
 Q('A knowledge base article should specify…',['Steps, prerequisites, and validation','Private passwords','Speculative diagnoses as fact'],0,'Repeatable and safe guidance helps other technicians.')])
 ]},
{
 id:'cloud',title:'Cloud, Email & Microsoft 365',subtitle:'Support cloud accounts, email, file sync, collaboration, and shared services.',icon:'cloud',level:'Intermediate',accent:'#5fb1d4',category:'Cloud',outcomes:['Explain cloud and SaaS clearly','Triage common email and Teams symptoms','Understand identity, licenses, and cloud-file syncing'],
 lessons:[
 L('cloud-fundamentals','What cloud services actually are',18,'Cloud computing runs services on infrastructure managed by a provider.',[
 B('The service models','SaaS is a complete hosted app, such as web email. PaaS offers an environment for building applications. IaaS offers rented computing infrastructure. IT technicians usually support identity, devices, connectivity, and end-user access to these services.',['SaaS: software as a service.','PaaS: platform as a service.','IaaS: infrastructure as a service.']),
 B('Your part of the service','A cloud problem might stem from the vendor, local internet, browser cache, expired credentials, permissions, or a license. A cloud status page can help, but do not assume a vendor outage without confirmation.',['Determine one user or many.','Try an approved alternate browser or device.','Review service health if available.'])
 ],['Choose SaaS, PaaS, or IaaS for a hosted email application.','Explain why a cloud app can fail even when the user’s laptop is fine.'],[
 Q('A hosted email application is usually…',['SaaS','A CPU','A local printer'],0,'A complete hosted application is SaaS.'),
 Q('When many users lose cloud access, check…',['Shared connectivity and service health','Every mouse battery','Only one browser’s bookmarks'],0,'Broad scope suggests a shared dependency.')]),
 L('m365-identity','Microsoft 365 accounts and licensing',19,'Many workplace account issues combine identity, licensing, and policy.',[
 B('Understand the layers','A user can exist in an identity directory yet lack permission to use a particular application. A product license may enable services, and Conditional Access or device policies can affect sign-in. Terms and admin interfaces may change over time.',['Identity proves who the user is.','Licensing enables product entitlements.','Authorization/policy controls permitted actions.']),
 B('Troubleshoot without bypassing controls','Collect the exact error, user impact, sign-in method, service, and whether others are affected. Check documented admin information only if your role permits it. Never disable MFA or security policy just to make a sign-in succeed.',['Use approved identity verification for resets.','Respect delegated admin roles.','Escalate unclear policy blocks to identity administrators.'])
 ],['Write a checklist for “I can log in but I cannot open Teams.”','Explain why a license and permission are not identical.'],[
 Q('A user exists in the directory but an app is unavailable. A possible cause is…',['Licensing or access policy','Broken monitor cable only','Printer ink'],0,'Entitlements and policy can block an app.'),
 Q('Should a support tech disable MFA to resolve a sign-in complaint?',['Not without explicit authorized policy','Yes, always'],0,'Follow approved identity support processes.')]),
 L('outlook-teams','Troubleshooting Outlook and Teams',19,'Start with whether the problem follows the account or device.',[
 B('Scope and symptoms','For email, determine send vs. receive, desktop vs. web client, network availability, mailbox limits, and exact errors. For meetings, check microphone permission, input device, app selection, and network conditions.',['A web-versus-desktop comparison is useful.','Confirm whether others are impacted.','Do not read private messages unless authorized.']),
 B('Verify end to end','After a fix, have the user send a permitted test message, join a test call, or share audio. Avoid changing organization-wide settings when the issue affects one device.',['Collect version and timestamps.','Use approved repair and sign-in steps.','Document any continuing vendor-side incident.'])
 ],['Write a flowchart for “my Teams microphone is not working.”','Describe a safe test for email sending and receiving.'],[
 Q('Teams audio fails on only one laptop. First check…',['Microphone selection and permissions','Entire company domain DNS','Replace every headset'],0,'Start with local device and app configuration.'),
 Q('Email works in webmail but not desktop Outlook. Suspect…',['Desktop app or local profile','All mail servers worldwide','The mouse'],0,'The difference narrows the fault domain.')]),
 L('sync-backups','Cloud files and collaboration',17,'A visible cloud folder does not guarantee every file is fully synced.',[
 B('How sync works','A sync client uploads and downloads file changes. Cloud-only placeholders may require connectivity to open. Conflicts, quota, account mismatch, and permissions can prevent access or produce duplicate copies.',['Check sync status and account identity.','Confirm online vs. locally cached files.','Respect permissions on shared folders.']),
 B('Recovery and sharing','Before deleting/relinking a folder, check whether local unsynced changes exist. Use approved version history, retention, or restore features where available. Sharing links should be scoped to appropriate people.',['Do not promise that cloud sync is a backup.','Review what is shared with whom.','Escalate data-loss symptoms promptly.'])
 ],['Explain why a cloud-only document might fail to open offline.','Describe a safe first response to a user reporting missing synchronized files.'],[
 Q('A cloud-only file may require…',['An internet connection','A new CPU','A VGA cable'],0,'Cloud-only content often needs retrieval from the service.'),
 Q('Before resetting a sync client, check…',['Unsynced local changes','Keyboard backlight','Printer paper'],0,'Preserve files that have not yet uploaded.')])
 ]},
{
 id:'career',title:'IT Career & Job Readiness',subtitle:'Turn skills into portfolio proof, interview answers, and a junior support job plan.',icon:'briefcase',level:'All levels',accent:'#e4b04f',category:'Career',outcomes:['Build a simple support portfolio','Practice common support interview responses','Plan realistic next steps toward entry-level roles'],
 lessons:[
 L('it-jobs','Entry-level IT roles explained',16,'IT careers have multiple entry points; not all require heavy coding.',[
 B('Common job titles','Help Desk Technician and Service Desk Analyst usually handle first-line tickets. Desktop Support Technician works more hands-on with endpoints. IT Support Specialist combines accounts, devices, software, and basic networks. Roles differ by organization.',['Read job descriptions, not just job titles.','Look for Windows, networking, ticketing, and customer service.','Home labs and campus experience can count as practical examples.']),
 B('What employers need to see','Show that you can isolate a fault, prioritize risk, explain your actions, protect data, and know when to escalate. You can demonstrate these skills using a small practice portfolio.',['Clear communication often matters as much as technical recall.','Do not claim skills or credentials you do not have.','Describe outcomes and your actual contribution.'])
 ],['Read a help desk job posting and highlight five required skills.','Match two requirements to lessons you completed here.'],[
 Q('Which is often central to first-line support?',['Ticket triage and communication','Designing microchips','Training large language models'],0,'Help desk focuses on supporting users and resolving incidents.'),
 Q('If you lack a listed tool, a truthful response is…',['Explain adjacent experience and a learning plan','Claim years of use','Avoid the topic entirely'],0,'Concrete transfer skills help without misrepresentation.')]),
 L('home-lab','Build a free, safe home lab',21,'A small demonstration project can make technical understanding visible.',[
 B('Create a learning environment','Use your own device or an isolated virtual machine you control. Practice checking system info, creating local files, reviewing task manager, and reading network settings. Do not test against school or work networks without authorization.',['Document the symptom, test, result, and screenshot.','Keep personal details out of public portfolios.','Make a restore point or snapshot where practical.']),
 B('Three portfolio projects','1. A “connected but no internet” diagnosis decision tree. 2. A mock printer support ticket with tests and escalation. 3. A one-page Windows performance troubleshooting guide. A polished, truthful explanation beats a giant collection of unverified scripts.',['Include tools used, actual observations, and lessons learned.','Mark simulated cases clearly.','Use plain language and reproducible steps.'])
 ],['Create one mock ticket using this website’s ticket template.','Capture the steps of a read-only system information check.'],[
 Q('Best safe practice lab?',['An owned device or isolated VM','An unauthorized employer server','An unknown neighbor’s router'],0,'Use environments you own or are explicitly authorized to test.'),
 Q('A portfolio should make clear when a case is…',['Simulated','Guaranteed production experience','A professional certificate'],0,'Label simulations honestly.')]),
 L('interviews','IT support interview practice',19,'A good answer shows your process even when you do not know the fix.',[
 B('The troubleshooting question','Question: “A user has no internet—what do you do?” Explain: clarify scope, verify local connection, inspect IP/gateway/DNS, compare another device, test carefully, apply a safe fix, verify, document. You do not need to recite a single magic command.',['Think aloud with a structured process.','Ask clarifying questions.','Mention user communication and escalation.']),
 B('The behavioral question','For “Tell me about a time you helped someone,” use Situation → Task → Action → Result (STAR). Pick an honest academic, volunteer, personal, or work example. Be concrete about what YOU did.',['Keep answers focused, roughly one or two minutes.','Acknowledge limitations without underselling the learning.','Prepare thoughtful questions about tools, training, and escalation.'])
 ],['Answer “A printer is offline for 20 people” using the troubleshooting process.','Draft a STAR story about helping someone with a technical problem.'],[
 Q('When you do not know the fix in an interview, best approach?',['Explain safe investigation and escalation','Invent an answer confidently','Say you never ask questions'],0,'A sound process is valuable.'),
 Q('STAR stands for…',['Situation, Task, Action, Result','Software, Tool, Access, Router','Speed, Test, Admin, Recovery'],0,'STAR structures real examples.')]),
 L('next-steps','Your 30-day skill plan',16,'Progress comes from repeatable practice, not cramming jargon.',[
 B('A practical sequence','Week 1: foundations and OS basics. Week 2: networking and device diagnostics. Week 3: security and simulated support tickets. Week 4: interview drills, portfolio, and applications. Repeat weaker quiz lessons until you can explain them without notes.',['Spend 20–30 minutes most days.','Create two mock tickets each week.','Practice explaining a topic out loud in simple words.']),
 B('Where certifications fit','Certifications such as CompTIA A+ can provide a study target, but this website is not an official certification course, exam voucher, or accredited credential. Always compare current vendor exam objectives with your study plan.',['Use official published exam objectives for exam prep.','Pair reading with hands-on practice.','Target junior roles as your skills grow.'])
 ],['Choose one realistic 30-day goal: a completed course, two mock tickets, or one portfolio guide.','Review missed quiz questions and write a short explanation for each.'],[
 Q('What is the strongest way to prepare for support work?',['Study concepts and practice safe scenarios','Memorize only acronyms','Skip troubleshooting'],0,'Real cases develop decision-making.'),
 Q('Does completion of this site grant an industry certification?',['No, it is independent training','Yes, it guarantees CompTIA A+'],0,'This is a self-study course website, not an issuing certification body.')])
 ]}
];
const GLOSSARY=[
 ['Access point','Device that provides wireless connectivity to a network.'],['Authentication','Verifying an identity, such as by password and multifactor sign-in.'],['Authorization','Determining what an authenticated user is permitted to access.'],['Backup','A recoverable copy of data retained separately or with recovery history.'],['BIOS/UEFI','Firmware that initializes computer hardware before the operating system loads.'],['Bootloader','Software that starts an operating system.'],['CPU','Central processing unit; executes instructions.'],['DHCP','Service that automatically assigns network configuration to clients.'],['DNS','System that resolves names such as example.com to addresses.'],['Driver','Software that allows an OS to communicate with specific hardware.'],['Endpoint','A user-facing networked device such as a laptop or phone.'],['Escalation','Handing an issue to the right team or authority when needed.'],['Firewall','Security control that filters network traffic based on rules.'],['Gateway','Router or next hop used to reach addresses beyond the local subnet.'],['Incident','Unplanned interruption or degradation of a service.'],['IP address','Network-layer address assigned to an interface.'],['Kernel','Core operating system software managing hardware and processes.'],['LAN','Local area network such as a home or office network.'],['Least privilege','Giving users and systems only the access needed for a task.'],['MFA','Multifactor authentication; uses more than one independent factor.'],['Operating system','Software layer managing files, hardware, programs, and access.'],['Patch','Software update addressing a defect or vulnerability.'],['Ping','Diagnostic command testing whether a destination replies to ICMP requests.'],['POST','Power-on self-test; startup checks run by firmware.'],['RAM','Volatile working memory used by running programs.'],['Router','Network device forwarding traffic between different IP networks.'],['SaaS','Software as a Service; provider-hosted application.'],['SLA','Service level agreement; defined service commitments where applicable.'],['SSD','Solid-state drive used for persistent storage.'],['SSID','Name identifying a Wi-Fi network.'],['Subnet','Logical portion of an IP network indicated by a prefix/mask.'],['Switch','Device that connects endpoints inside a local network.'],['Ticket','Tracked record of a service issue or request.'],['Troubleshooting','Systematic investigation and resolution of a problem.'],['VPN','Virtual private network; creates a protected network connection in approved configurations.'],['Workaround','Temporary way to restore function pending a full fix.']
];
const SCENARIOS=[
 {id:'s1',category:'Networking',title:'Connected to Wi-Fi, websites will not load',difficulty:'Easy',report:'“My laptop says it is connected to Wi-Fi, but Chrome cannot open any website. My roommate is online just fine.”',prompt:'What is the best first move?',choices:['Reset the entire building router','Check laptop IP settings, gateway and whether any site works','Reinstall the browser immediately'],correct:1,why:'The problem may be isolated to one laptop. Confirm scope, link, IP, gateway, and DNS before making changes.',next:'The laptop has a 169.254.x.x address. That often indicates a DHCP problem. Investigate the local connection and DHCP availability per policy.'},
 {id:'s2',category:'Accounts',title:'Employee cannot access a team folder',difficulty:'Easy',report:'“I can sign in, but the shared budget folder says Access denied. My coworker can see it.”',prompt:'What should you do?',choices:['Make the entire folder public','Confirm approved access and review the relevant group permissions','Ask the coworker to share their password'],correct:1,why:'Authentication succeeded; authorization might not. Confirm approval and use the correct access workflow.',next:'Check membership and the access request workflow. Do not expand permissions beyond what is authorized.'},
 {id:'s3',category:'Hardware',title:'New monitor is blank',difficulty:'Easy',report:'“I connected a new display to my laptop dock. It says No signal.”',prompt:'What is the safest first diagnostic action?',choices:['Check display power, input source, and cable/dock connection','Replace the CPU','Erase the laptop'],correct:0,why:'Follow the signal path from display power and selected input before disruptive changes.',next:'After confirming the connection, inspect OS display detection and the dock’s documented video support.'},
 {id:'s4',category:'Security',title:'Suspicious sign-in approval requests',difficulty:'Medium',report:'“My phone keeps asking me to approve account logins, but I am not signing in.”',prompt:'Which response is best?',choices:['Approve one to make the alerts stop','Deny prompts and immediately report the suspicious activity','Turn off all account security'],correct:1,why:'Unexpected MFA prompts can mean someone has credentials or is attempting an attack.',next:'Follow incident procedures, verify through approved channels, and assist with account protection as directed.'},
 {id:'s5',category:'Windows',title:'Laptop gets slower every afternoon',difficulty:'Medium',report:'“Apps become sluggish around 3 PM. Restarting temporarily helps.”',prompt:'How should you investigate?',choices:['Record workload, check CPU/RAM/disk utilization and logs during the slowdown','Immediately reinstall the OS','Delete all user downloads'],correct:0,why:'Measure what is happening while the issue occurs. Multiple causes can explain temporary slowness.',next:'Correlate resource usage with scheduled tasks, updates, heat, apps, and free disk space.'},
 {id:'s6',category:'Cloud',title:'Outlook desktop fails, webmail works',difficulty:'Medium',report:'“Email loads in the web browser but the Outlook desktop app keeps asking me to sign in.”',prompt:'What is a reasonable next step?',choices:['Assume the entire mail service is offline','Investigate local Outlook profile/session and approved sign-in repair steps','Disable company MFA'],correct:1,why:'A functioning web client suggests a desktop-app or local authentication path problem.',next:'Collect exact error and version; check organization guidance before resetting credentials or profiles.'},
 {id:'s7',category:'Printers',title:'Everyone on one floor cannot print',difficulty:'Medium',report:'“We all sent jobs to the same shared printer, but nothing comes out.”',prompt:'Where should you focus first?',choices:['Inspect printer/service status and shared queue','Reinstall Windows on every computer','Tell everyone their accounts are compromised'],correct:0,why:'A shared failure points to printer, print server, queue, or network path rather than individual apps.',next:'Check printer panel, power, connection, queue, and approved service status. Escalate shared print server issues.'},
 {id:'s8',category:'Security',title:'Employee reports suspected ransomware',difficulty:'Advanced',report:'“My files suddenly have unfamiliar extensions, and there is a payment note on screen.”',prompt:'What is the responsible response?',choices:['Experiment with decryption tools from a random website','Follow incident response and escalate immediately, preserving evidence','Pay using your own credit card'],correct:1,why:'Possible ransomware is a serious security incident requiring controlled response and organizational procedures.',next:'Record details and follow incident handler instructions on containment and evidence. Do not attempt unsanctioned remediation.'}
];
